choose.when:
select 'todo' resource_type, concat('', r.id) id, r.content title, r.remark body, r.label tags, coalesce(r.create_time, r.plan_end_time) created_at, coalesce(r.update_time, coalesce(r.create_time, r.plan_end_time), '1970-01-01 00:00:00') updated_at from px_to_do r where 1 = 1 and (r.parent_id = 0 or r.parent_id is null)
and r.create_by in #{owner}
and 1 = 0

select 'commemoration' resource_type, concat('', r.id) id, r.name title, r.remark body, '' tags, r.create_time created_at, coalesce(r.update_time, r.create_time, '1970-01-01 00:00:00') updated_at from px_commemoration_day r where 1 = 1 and r.del_flag = '0'
and r.create_by in #{owner}
and 1 = 0

select 'recipe' resource_type, concat('', r.id) id, r.title title, r.notes body, '' tags, r.create_time created_at, coalesce(r.update_time, r.create_time, '1970-01-01 00:00:00') updated_at from px_recipe r where 1 = 1 and r.del_flag = '0'
and r.create_by in #{owner}
and 1 = 0

select 'shopping' resource_type, concat('', r.id) id, r.name title, r.remark body, '' tags, r.create_time created_at, coalesce(r.update_time, r.create_time, '1970-01-01 00:00:00') updated_at from px_shopping_list r where 1 = 1 and r.del_flag = '0'
and r.create_by in #{owner}
and 1 = 0

where.if:
and (

    orand
    exists (select 1 from px_resource_tag_rel rel where rel.owner_id=#{userId}
        and rel.resource_type=documents.resource_type and rel.resource_id=documents.id
        and rel.tag_id in #{tagId})

)
